+              </div>
+              <nav aria-label="Primary">
+                <ul>
+                  <li><a href="#faq">FAQ</a></li>
+                  <li><a href="#care">Care tips</a></li>
+                </ul>
+              </nav>
+            </div>
+          </header>
+        `;
+      }
+
+      function Hero() {
+        return `
+          <section class="hero app-shell" aria-labelledby="page-title">
+            <div>
+              <span class="eyebrow">Friendly answers for curious cat people</span>
+              <h1 id="page-title">Cat FAQ</h1>
+              <p>
+                Quick, practical answers about common cat behaviors, care routines,
+                and the small mysteries that make cats such memorable companions.
+              </p>
+            </div>
