      .quick-facts {
        display: grid;
        grid-template-columns: repeat(3, 1fr);
        gap: 0.75rem;
        margin-top: 1rem;
      }

      .quick-fact {
        border: 1px solid var(--border);
        border-radius: 18px;
        background: rgba(255, 255, 255, 0.62);
        padding: 0.9rem;
      }

      .quick-fact strong {
        display: block;
        font-size: 1.35rem;
        line-height: 1.1;
      }

      .quick-fact span {
        color: var(--muted);
        font-size: 0.9rem;
      }

      .faq-section {
        padding: 0 0 clamp(3rem, 7vw, 6rem);
      }

      .section-heading {
        max-width: 44rem;
        margin-bottom: 1.5rem;
      }

      .section-heading h2 {
        font-size: clamp(2rem, 5vw, 3.6rem);
      }

      .section-heading p {
        margin: 0.85rem 0 0;
        color: var(--muted);
      }

      .faq-list {
        display: grid;
        gap: 0.85rem;
      }

      .example {
        overflow: hidden;
        border: 1px solid var(--border);
        border-radius: var(--radius-md);
        background: rgba(255, 250, 243, 0.82);
        box-shadow: 0 12px 34px rgba(50, 39, 30, 0.08);
      }

      .question-heading {
        margin: 0;
      }

      .question-button {
        display: flex;
        width: 100%;
        min-height: 56px;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        border: 0;
        background: transparent;
        color: var(--text);
        padding: 1.1rem clamp(1rem, 3vw, 1.35rem);
        font: inherit;
        font-size: clamp(1rem, 2.5vw, 1.15rem);
        font-weight: 850;
        text-align: left;
        cursor: pointer;
      }

      .question-button::after {
        content: "+";
        display: grid;
        flex: 0 0 auto;
        width: 2rem;
        height: 2rem;
        place-items: center;
        border: 1px solid var(--border);
        border-radius: 50%;
        background: var(--surface-strong);
        color: var(--accent-dark);
        font-size: 1.35rem;
        line-height: 1;
      }

      .question-button[aria-expanded="true"]::after {
        content: "−";
      }

      .details {
        padding: 0 clamp(1rem, 3vw, 1.35rem) 1.25rem;
      }

      .details p {
        max-width: 68ch;
        margin: 0;
        color: var(--muted);
      }

      footer {
        border-top: 1px solid var(--border);
        padding: 1.5rem 0 2rem;
        color: var(--muted);
        font-size: 0.95rem;
