  </head>
  <body>
    <a class="skip-link" href="#maincontent">Skip to main content</a>
    <div id="root"></div>

    <script>
      const faqs = [
        {
          question: "Why do cats purr?",
          answer:
            "Cats often purr when they feel relaxed, but purring can also be a self-soothing behavior when they are stressed, recovering, or asking for attention."
        },
        {
          question: "How much sleep do cats need?",
          answer:
            "Most adult cats sleep 12 to 16 hours a day. Kittens and senior cats may sleep even more because growth and recovery require extra rest."
        },
        {
          question: "Why does my cat knead blankets?",
          answer:
            "Kneading is a comforting behavior that starts in kittenhood. Adult cats may knead soft surfaces when they feel secure, affectionate, or ready to settle down."
        },
        {
          question: "Do cats need daily play?",
          answer:
            "Yes. Short daily play sessions help cats practice natural hunting behaviors, reduce boredom, and support a healthy weight."
        },
        {
          question: "Why do cats like boxes?",
          answer:
            "Boxes offer warmth, hiding space, and a secure vantage point. For many cats, a box feels like a safe little room they can control."
        }
      ];

      function Header() {
        return `
          <header class="app-shell">
            <div class="topbar">
              <div class="brand" aria-label="Cat FAQ home">
                <span class="brand-mark" aria-hidden="true">🐾</span>
                <span>Catwise</span>
              </div>
              <nav aria-label="Primary">
                <ul>
                  <li><a href="#faq">FAQ</a></li>
                  <li><a href="#care">Care tips</a></li>
                </ul>
              </nav>
            </div>
          </header>
        `;
      }

      function Hero() {
        return `
          <section class="hero app-shell" aria-labelledby="page-title">
            <div>
              <span class="eyebrow">Friendly answers for curious cat people</span>
              <h1 id="page-title">Cat FAQ</h1>
              <p>
                Quick, practical answers about common cat behaviors, care routines,
                and the small mysteries that make cats such memorable companions.
              </p>
            </div>
            <aside class="hero-card" aria-label="Cat care snapshot" id="care">
              <div class="cat-portrait" aria-hidden="true">😺</div>
              <div class="quick-facts">
                <div class="quick-fact">
                  <strong>12–16</strong>
                  <span>hours of sleep</span>
                </div>
                <div class="quick-fact">
                  <strong>2+</strong>
                  <span>play sessions</span>
                </div>
                <div class="quick-fact">
                  <strong>1</strong>
                  <span>clean litter box</span>
                </div>
              </div>
            </aside>
          </section>
        `;
      }

      function FAQItem(item, index) {
        const buttonId = `faq-question-${index + 1}`;
        const panelId = `faq-answer-${index + 1}`;

        return `
          <div class="example">
            <h3 class="question-heading">
              <button
                class="question-button"
                type="button"
                id="${buttonId}"
                aria-expanded="true"
                aria-controls="${panelId}"
              >
                ${item.question}
              </button>
            </h3>
            <div class="details" id="${panelId}" aria-labelledby="${buttonId}">
              <p>${item.answer}</p>
            </div>
          </div>
        `;
      }

      function FAQSection(items) {
        return `
          <section class="faq-section app-shell" id="faq" aria-labelledby="faq-heading">
            <div class="section-heading">
              <h2 id="faq-heading">Questions cat owners ask all the time</h2>
              <p>
                Expand any question to read the answer. Each section works independently,
                so you can keep the details you need open while browsing.
              </p>
            </div>
            <div class="faq-list">
              ${items.map(FAQItem).join("")}
            </div>
          </section>
        `;
      }

      function Footer() {
        return `
          <footer>
            <div class="app-shell">
              <p>Catwise provides general cat-care education and is not a substitute for veterinary advice.</p>
            </div>
          </footer>
        `;
      }

      function App() {
        return `
          ${Header()}
          <main id="maincontent" tabindex="-1">
            ${Hero()}
            ${FAQSection(faqs)}
          </main>
          ${Footer()}
        `;
      }

      function initializeDisclosures() {
        document.querySelectorAll(".question-button").forEach((button) => {
          const panel = document.getElementById(button.getAttribute("aria-controls"));

          button.setAttribute("aria-expanded", "false");
          panel.hidden = true;

          button.addEventListener("click", () => {
            const isOpen = button.getAttribute("aria-expanded") === "true";
            button.setAttribute("aria-expanded", String(!isOpen));
            panel.hidden = isOpen;
          });

          button.addEventListener("keydown", (event) => {
            if (event.key === "Escape" && button.getAttribute("aria-expanded") === "true") {
              button.setAttribute("aria-expanded", "false");
              panel.hidden = true;
              button.focus();
            }
          });
        });
      }

      document.getElementById("root").innerHTML = App();
      initializeDisclosures();
    </script>
  </body>
</html>
